#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int cost = 0, i = 0, j = 0, limit = 0, n = 0, value = 0;
    // limit 是时间容量，a[j] 表示时间不超过 j 时的最大价值。
    limit = read();
    n = read();
    for (i = 0; i < n; i += 1) {
        cost = read();
        // 每株只处理一次，cost 是时间，value 是收益。
        value = read();
        // 容量倒序更新，保证 a[j-cost] 尚未使用当前这一株草药。
        for (j = limit; j > (cost - 1); j += -1) {
            a[j] = mx(a[j], (a[(j - cost)] + value));
        }
    }
    // 允许不采或不耗尽时间，直接输出总时间上限的最佳价值。
    emit(a[limit]);
    return 0;
}

