import sys

_tokens = iter(sys.stdin.read().split())


def read():
    return int(next(_tokens))


def readstr(a):
    s = next(_tokens)
    if s == "-":
        return 0
    for i, c in enumerate(s):
        a[i] = ord(c)
    return len(s)


def emit(x):
    print(x, end=" ")


def emitstr(a, n):
    print("".join(chr(x) for x in a[:n]) if n else "-", end=" ")


def mn(a, b):
    return min(a, b)


def mx(a, b):
    return max(a, b)


a = [0] * 20000
b = [0] * 20000
d = [0] * 20000
e = [0] * 20000
cost = i = j = limit = n = value = 0
# 容量是总时间上限，a[j] 保存不超过该容量的最大价值。
limit = read()
n = read()
for i in range(n):
    cost = read()
    # 每株读到时间 cost 和价值 value，最多选择一次。
    value = read()
    # 必须从大容量向小容量走，避免本株在本轮被重复使用。
    for j in range(limit, (cost - 1), (-1)):
        a[j] = mx(a[j], (a[(j - cost)] + value))
# 输出容量上限的最佳价值，剩余时间未用完也合法。
emit(a[limit])

