use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut cost: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut limit: i32 = 0;
    let mut n: i32 = 0;
    let mut value: i32 = 0;
    // limit 是时间容量，a[j] 表示时间不超过 j 时的最大价值。
    limit = reader.read();
    n = reader.read();
    i = 0;
    while i < n {
        cost = reader.read();
        // 每株只处理一次，cost 是时间，value 是收益。
        value = reader.read();
        j = limit;
        // 容量倒序更新，保证 a[j-cost] 尚未使用当前这一株草药。
        while j > (cost - 1) {
            a[(j) as usize] = mx(a[(j) as usize], (a[(j - cost) as usize] + value));
            j += -1;
        }
        i += 1;
    }
    // 允许不采或不耗尽时间，直接输出总时间上限的最佳价值。
    emit(a[(limit) as usize]);
}
